import numpy as np

def check_large_x_y():
    # Check if there exist x, y > 3 such that 3x + 3y - xy - 8*sqrt(xy) - 1 >= 0
    # Let x = 3 + dx, y = 3 + dy, where dx, dy > 0.
    for dx in np.linspace(0.1, 10, 100):
        for dy in np.linspace(0.1, 10, 100):
            x = 3 + dx
            y = 3 + dy
            if 3*x + 3*y - x*y - 8*np.sqrt(x*y) - 1 >= 0:
                return (x, y)
    return None

print(check_large_x_y())
